#include <iostream>
#include <memory>
#include <utility>
#include <string>
#include <vector>

// ── A moveable buffer class ────────────────────────────────────────────────
class Buffer {
public:
    explicit Buffer(std::size_t n)
        : data_(std::make_unique<int[]>(n)), size_(n) {
        std::cout << "  Buffer(" << n << ") constructed\n";
    }

    ~Buffer() {
        std::cout << "  ~Buffer(size=" << size_ << ") destroyed\n";
    }

    // Copy constructor — O(n) deep copy
    Buffer(const Buffer& other)
        : data_(std::make_unique<int[]>(other.size_)), size_(other.size_) {
        std::copy(other.data_.get(), other.data_.get() + size_, data_.get());
        std::cout << "  Buffer(copy, n=" << size_ << ")\n";
    }

    // Move constructor — O(1): steal the pointer
    Buffer(Buffer&& other) noexcept
        : data_(std::move(other.data_)), size_(other.size_) {
        other.size_ = 0;
        std::cout << "  Buffer(move)\n";
    }

    // Move assignment — O(1)
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            data_ = std::move(other.data_);
            size_ = other.size_;
            other.size_ = 0;
            std::cout << "  Buffer::operator=(move)\n";
        }
        return *this;
    }

    std::size_t size() const { return size_; }

private:
    std::unique_ptr<int[]> data_;
    std::size_t size_;
};

// ── Factory: NRVO ensures zero copies/moves ────────────────────────────────
Buffer makeBuffer(std::size_t n) {
    Buffer b(n);
    return b;          // Trust NRVO — don't write std::move(b)!
}

// ── Perfect forwarding into a container ───────────────────────────────────
template<typename T>
void logAndStore(std::vector<T>& container, T&& item) {
    std::cout << "  forwarding item\n";
    container.push_back(std::forward<T>(item));
}

int main() {
    std::cout << "=== Day 13: Move Semantics ===\n\n";

    // ── 1. Move construction ───────────────────────────────────────────────
    std::cout << "[1] Move construction\n";
    Buffer a(1000);
    Buffer b = std::move(a);          // move constructor called
    std::cout << "  a.size after move: " << a.size() << " (now 0)\n";
    std::cout << "  b.size after move: " << b.size() << "\n\n";

    // ── 2. NRVO — ideally zero copies and zero moves ───────────────────────
    std::cout << "[2] NRVO (Return Value Optimization)\n";
    Buffer c = makeBuffer(500);       // watch: likely no copy or move printed
    std::cout << "  c.size: " << c.size() << "\n\n";

    // ── 3. Move assignment ─────────────────────────────────────────────────
    std::cout << "[3] Move assignment\n";
    Buffer d(10);
    d = makeBuffer(20);               // temporary rvalue → move assignment
    std::cout << "  d.size after move assign: " << d.size() << "\n\n";

    // ── 4. std::move with string ───────────────────────────────────────────
    std::cout << "[4] std::move with string\n";
    std::string s = "hello world";
    std::string t = std::move(s);
    std::cout << "  s after move: '" << s << "' (empty/unspecified)\n";
    std::cout << "  t after move: '" << t << "'\n\n";

    // ── 5. Perfect forwarding ──────────────────────────────────────────────
    std::cout << "[5] Perfect forwarding\n";
    std::vector<std::string> words;
    std::string word = "move-me";
    logAndStore(words, std::move(word));          // moves into vector
    logAndStore(words, std::string("rvalue"));    // rvalue: moves directly
    std::cout << "  stored: " << words[0] << ", " << words[1] << "\n";

    return 0;
}
